  nextUrl: string | null,
  root: RootRouteTree<CacheNode>
): void {
  currentRouteCacheVersion++
  currentSegmentCacheVersion++

  pingVisibleLinks(nextUrl, root)
  pingInvalidationListeners(nextUrl, root)
